import React, { useEffect, useState } from "react";
import { StyleSheet, Text, View } from "react-native";
import { Player, PlayerView, Source, SourceType } from "bitmovin-player-react-native";

interface MountedPlayer {
  player: Player;
  load: () => void;
  fail: () => void;
  playing: () => void;
}

export default function MinimalPlayer() {
  const [mounted, setMounted] = useState<MountedPlayer | null>(null);
  const [status, setStatus] = useState("Preparing player");

  useEffect(() => {
    let active = true;
    let sourceInitialization: Promise<void> | undefined;
    const player = new Player({
      licenseKey: "YOUR_PLAYER_KEY",
      playbackConfig: { isAutoplayEnabled: true, isMuted: true },
    });
    const source = new Source({
      url: "https://example.com/video/master.m3u8",
      type: SourceType.HLS,
    });
    const fail = () => { if (active) setStatus("Playback failed"); };
    const initialization = player.initialize();
    setMounted(null);
    void initialization.then(() => {
      if (!active) return;
      setMounted({ player, fail, playing: () => { if (active) setStatus("Playing"); }, load: () => {
        if (!active || sourceInitialization) return;
        sourceInitialization = source.initialize();
        void sourceInitialization.then(() => {
          if (active) player.loadSource(source);
        }, fail);
      } });
    }, fail);

    return () => {
      active = false;
      void (async () => {
        await initialization.catch(() => {});
        await sourceInitialization?.catch(() => {});
        player.destroy();
        source.destroy();
      })().catch(() => console.error("Player cleanup failed."));
    };
  }, []);

  return <View style={styles.screen}>
    {mounted && <PlayerView player={mounted.player} style={styles.video}
      onPlayerViewReady={mounted.load}
      onPlayerError={mounted.fail} onSourceError={mounted.fail}
      onPlaying={mounted.playing} />}
    <Text>{status}</Text>
  </View>;
}

const styles = StyleSheet.create({
  screen: { flex: 1 },
  video: { width: "100%", height: 240 },
});

const player: PlayerConfig = {
    playbackConfig: { isAutoplayEnabled: draft.autoplay, isMuted: draft.muted },
    ...(forwardDuration !== undefined ? { bufferConfig: { audioAndVideo: { forwardDuration } } } : {}),
    ...(maxBitrate !== undefined ? { adaptationConfig: { maxSelectableBitrate: maxBitrate } } : {}),
};

const source: SourceConfig = {
  url, type, ...(title ? { title } : {}), ...(poster ? { poster } : {}),
  ...(subtitleUrl ? { subtitleTracks: [{ url: subtitleUrl, label: subtitleLabel, language: subtitleLanguage,
    identifier: "player-lab-external", format: SubtitleFormat.VTT, isDefault: subtitleDefault }] } : {}),
  ...(startOffset !== undefined || reference !== undefined ? { options: {
    ...(startOffset !== undefined ? { startOffset } : {}),
    ...(reference !== undefined ? { startOffsetTimelineReference: reference } : {}),
  } } : {}),
};

useEffect(() => {
  if (!viewReady || !active.current) return;
  snapshots.current?.sourceChanged();
  operationContext.reset();
  setDvr(null);
  append(`load ${source.title || "source"}`);
  // Player.load is void in wrapper 1.29.0; native Source/Player error events report failures.
  void loadOwnedSource(player, source).then(() => operationContext.refresh()).catch(() => { if (active.current) append("Source initialization failed; inspect source events or retry after the pending initializer settles."); });
  observed.current?.sourceLoad();
}, [source, player, viewReady, append, operationContext]);

export function restoreProfile(profile: ConfigurationProfile, current: ConfigurationDraft, platform: ProfilePlatform, confirmSdk = false): ConfigurationDraft {
  const validated = validateProfile(profile, platform);
  if (validated.sdkVersion !== CURRENT_SDK_VERSION && !confirmSdk) throw new ConfigurationProfileError("sdk");
  const preset = validated.sourcePreset === null ? null : presetForId(validated.sourcePreset, platform);
  return draftFromProfile(validated, current, preset);
}

styleConfig: {
  userInterfaceType: UserInterfaceType.Bitmovin,
  playerUiJs: WEBUI_JS,
  playerUiCss: WEBUI_CSS,
  ...playerConfig.styleConfig,
},

const viewConfig: PlayerViewConfig = { ...settings.view, uiConfig: {
  variant: new CustomUi(uiMode.factoryFunction ?? "bitmovin.playerui.UIFactory.buildSmallScreenUI"), ...settings.webUi,
} satisfies WebUiConfig };

one("Player.setVideoQuality", { ...value, initial: "auto", label: "Quality ID (getAvailableVideoQualities, or auto)" }, (raw) => raw, (v) => player.setVideoQuality(v));
one("Player.setAudioTrack", { ...value, label: "Audio track identifier (getAvailableAudioTracks)" }, (raw) => raw, (v) => player.setAudioTrack(v));
one("Player.setSubtitleTrack", { ...value, label: "Subtitle identifier (blank disables subtitles)" }, (raw) => raw || undefined, (v) => player.setSubtitleTrack(v));

const analyticsConfig = playerConfig.analyticsConfig ? {
  ...playerConfig.analyticsConfig,
  licenseKey: Object.prototype.hasOwnProperty.call(settings.draft.apiSettings ?? {}, "PlayerConfig.analyticsConfig.licenseKey")
    ? playerConfig.analyticsConfig.licenseKey : ANALYTICS_LICENSE_KEY,
} : ANALYTICS_LICENSE_KEY ? { licenseKey: ANALYTICS_LICENSE_KEY } : undefined;
